```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int liczba;
    int rosnaco = 0, nierosnaco = 0;
    while (plik >> liczba) {
        string s = to_string(liczba);
        string t = s;
        sort(t.begin(), t.end());
        int posortowana = stoi(t);
        cout << liczba << " -> posortowane: " << posortowana;
        if (s == t) {
            cout << " -> rowne (cyfry rosnaco)" << endl;
            rosnaco++;
        } else {
            cout << " -> rozne" << endl;
            nierosnaco++;
        }
    }
    cout << "a) Cyfry rosnaco: " << rosnaco << endl;
    cout << "b) Cyfry nie rosnaco: " << nierosnaco << endl;
    return 0;
}
```

**Wyjasnienie**: Konwertujemy liczbe na string, sortujemy kopie stringa. Jesli oryginal == posortowany, cyfry byly juz w kolejnosci rosnacej (niemalejaco). Uzywamy `stoi()` do wypisania posortowanej wartosci jako liczby.

